class BillingSubscriptions(Resource):
    """Instances' subscriptions: what bills an instance, period after period.

    A subscription is pinned to a ``FLAT_FEE`` price of the instance's license version. Each
    period closes into a ``RENEWAL`` invoice; a base price billed in advance issues the first
    period's ``ACTIVATION`` invoice at once. While it is live, the instance's customer and
    license cannot change.
    """

    def get(self, instance_slug: str) -> InstanceBilling:
        """Return the instance's subscription, live or ``CANCELED``.

        Raises:
            NotFoundError: The instance was never subscribed.
        """
        return self._api.get(api_path("instances", instance_slug, "billing"), InstanceBilling)

    def subscribe(
        self,
        instance_slug: str,
        *,
        base_price_id: str,
        add_ons: Mapping[str, int] | None = None,
        voucher_code: str | None = None,
        trial_days: int | None = None,
        start_at: datetime | str | None = None,
        provider_kind: BillingProviderKind | None = None,
        collection_method: CollectionMethod | None = None,
        days_until_due: int | None = None,
    ) -> StartedSubscription:
        """Start billing an instance, and return its subscription with its first invoice.

        A ``CANCELED`` subscription is subscribed again.

        Args:
            instance_slug: The instance.
            base_price_id: An ``ACTIVE`` ``FLAT_FEE`` price of the instance's license version,
                which must be ``PUBLISHED``. The subscription stays pinned to it.
            add_ons: Add-ons to attach with it, as ``{addon_slug: quantity}``; the
                ``ACTIVATION`` invoice bills them.
            voucher_code: A voucher to redeem with the subscription.
            trial_days: Days of trial, 1 to 365: nothing is billed, and no usage counts, until
                it ends.
            start_at: What periods are counted from: now when omitted, at most one billing
                period ago otherwise.
            provider_kind: Who issues and collects the invoices: ``NOOP`` (the default), the
                organization itself through the handoff queue, or a connected provider.
            collection_method: ``SEND_INVOICE`` or ``CHARGE_AUTOMATICALLY``. The
                organization's default, read at each invoice, when omitted.
            days_until_due: Payment terms in days, 0 to 365. The organization's default when
                omitted.
        """
        body = {
            "basePriceId": base_price_id,
            **compact(
                {
                    "addOns": addon_quantities(add_ons),
                    "voucherCode": voucher_code,
                    "trialDays": trial_days,
                    "startAt": optional_datetime(start_at),
                    "providerKind": provider_kind,
                    "collectionMethod": collection_method,
                    "daysUntilDue": days_until_due,
                }
            ),
        }
        return self._api.send(
            "POST", api_path("instances", instance_slug, "billing"), StartedSubscription, body=body
        )

    def update(
        self,
        instance_slug: str,
        *,
        provider_kind: BillingProviderKind | None = None,
        collection_method: CollectionMethod | NotGiven | None = NOT_GIVEN,
        days_until_due: int | NotGiven | None = NOT_GIVEN,
    ) -> InstanceBilling:
        """Change a subscription's provider and terms from its next invoice on.

        What is not passed keeps its value; ``None`` restores the organization's default.
        Invoices already composed keep their own terms and provider.

        Args:
            instance_slug: The instance.
            provider_kind: Who issues and collects the invoices from the next one on.
            collection_method: ``SEND_INVOICE`` or ``CHARGE_AUTOMATICALLY``.
            days_until_due: Payment terms in days, 0 to 365.
        """
        body: dict[str, Any] = compact({"providerKind": provider_kind})
        if not isinstance(collection_method, NotGiven):
            body["collectionMethod"] = collection_method
        if not isinstance(days_until_due, NotGiven):
            body["daysUntilDue"] = days_until_due
        return self._api.send(
            "PATCH", api_path("instances", instance_slug, "billing"), InstanceBilling, body=body
        )

    def cancel(
        self,
        instance_slug: str,
        *,
        mode: CancellationMode | None = None,
        reason: str | None = None,
    ) -> CanceledSubscription:
        """Cancel a subscription.

        A trial ends at once, with no invoice. Otherwise ``AT_PERIOD_END`` (the default) lets the
        period paid for run out, then issues the ``FINAL`` invoice; ``IMMEDIATE`` issues it now.
        Cancellation changes billing only: entitlements and license dates stay yours to change.

        Args:
            instance_slug: The instance.
            mode: ``AT_PERIOD_END`` or ``IMMEDIATE``.
            reason: Why, up to 500 characters.
        """
        return self._api.send(
            "POST",
            api_path("instances", instance_slug, "billing", "cancel"),
            CanceledSubscription,
            body=compact({"mode": mode, "reason": reason}),
        )

    def reactivate(self, instance_slug: str) -> InstanceBilling:
        """Take back a cancellation scheduled for the period's end, before it."""
        return self._api.send(
            "POST", api_path("instances", instance_slug, "billing", "reactivate"), InstanceBilling
        )

    def schedule_plan_change(self, instance_slug: str, license_price_id: str) -> InstanceBilling:
        """Schedule a move to another ``FLAT_FEE`` price for the next boundary.

        That boundary's ``RENEWAL`` bills the old plan's arrears and the new plan's advance, and
        moves the instance to the new version, without proration. Scheduling another target
        replaces the change.

        Args:
            instance_slug: The instance.
            license_price_id: An ``ACTIVE`` ``FLAT_FEE`` price of a ``PUBLISHED`` license
                version, in the subscription's currency.
        """
        return self._api.send(
            "PUT",
            api_path("instances", instance_slug, "billing", "scheduled-change"),
            InstanceBilling,
            body={"licensePriceId": license_price_id},
        )

    def cancel_plan_change(self, instance_slug: str) -> InstanceBilling:
        """Drop the plan change scheduled for the next boundary."""
        return self._api.send(
            "DELETE",
            api_path("instances", instance_slug, "billing", "scheduled-change"),
            InstanceBilling,
        )

    def get_upcoming_invoice(self, instance_slug: str) -> InvoicePreview:
        """Return the invoice the next boundary will issue, from the usage so far, writing nothing.

        ``would_hold`` lists the meters whose usage journal fails a check and would hold it.
        """
        return self._api.get(
            api_path("instances", instance_slug, "billing", "upcoming-invoice"), InvoicePreview
        )

    def list_invoices(
        self,
        instance_slug: str,
        *,
        customer_slug: str | None = None,
        status: Sequence[InvoiceStatus] | None = None,
        kind: InvoiceKind | None = None,
        provider_kind: BillingProviderKind | None = None,
        overdue: bool | None = None,
        held: bool | None = None,
        handoff_status: HandoffStatus | None = None,
        issued_from: datetime | str | None = None,
        issued_to: datetime | str | None = None,
        boundary_from: datetime | str | None = None,
        boundary_to: datetime | str | None = None,
        updated_since: datetime | str | None = None,
        limit: int | None = None,
    ) -> builtins.list[InvoiceSummary]:
        """Return the invoices of an instance's subscription, across every time it was subscribed.

        The filters are those of :meth:`BillingInvoices.list`.
        """
        return self._api.list_all(
            api_path("instances", instance_slug, "invoices"),
            InvoiceSummary,
            params=invoice_query(
                customer_slug=customer_slug,
                status=status,
                kind=kind,
                provider_kind=provider_kind,
                overdue=overdue,
                held=held,
                handoff_status=handoff_status,
                issued_from=issued_from,
                issued_to=issued_to,
                boundary_from=boundary_from,
                boundary_to=boundary_to,
                updated_since=updated_since,
            ),
            limit=check_limit(limit),
        )


class BillingInstanceAddons(Resource):
    """The add-ons an instance holds, by the unit.

    Their entitlements apply at once; a subscription bills the quantity held at each boundary,
    without proration. An instance holds one version per add-on family.
    """

    def list(
        self, instance_slug: str, *, include_removed: bool = False
    ) -> builtins.list[InstanceAddon]:
        """Return the add-ons the instance holds, in attachment order, with the prices billed.

        Args:
            instance_slug: The instance.
            include_removed: Also return the add-ons removed from it.
        """
        return self._api.get_list(
            api_path("instances", instance_slug, "addons"),
            InstanceAddon,
            params={"includeRemoved": include_removed or None},
        )

    def attach(
        self, instance_slug: str, addon_slug: str, *, quantity: int | None = None
    ) -> InstanceAddon:
        """Give the instance an add-on version, and return the attachment.

        Moving to another version of the same add-on is a :meth:`detach`, then an attach.
        """
        body = {"addonSlug": addon_slug, **compact({"quantity": quantity})}
        return self._api.send(
            "POST", api_path("instances", instance_slug, "addons"), InstanceAddon, body=body
        )

    def set_quantity(self, instance_slug: str, addon_slug: str, quantity: int) -> InstanceAddon:
        """Change how many units of an add-on the instance holds, at once, a decrease included.

        It cancels a decrease the customer scheduled, even to the quantity held.
        """
        return self._api.send(
            "PATCH",
            api_path("instances", instance_slug, "addons", addon_slug),
            InstanceAddon,
            body={"quantity": quantity},
            idempotent=True,
        )

    def detach(self, instance_slug: str, addon_slug: str) -> None:
        """Remove an add-on from the instance, at once. Its entitlements drop; nothing is refunded."""
        self._api.send_empty("DELETE", api_path("instances", instance_slug, "addons", addon_slug))


class BillingInstanceVouchers(Resource):
    """The vouchers an instance redeemed."""

    def list(
        self, instance_slug: str, *, status: RedemptionStatus | None = None
    ) -> builtins.list[Redemption]:
        """Return the instance's redemptions, newest first."""
        return self._api.get_list(
            api_path("instances", instance_slug, "vouchers"), Redemption, params={"status": status}
        )

    def redeem(self, instance_slug: str, code: str) -> Redemption:
        """Redeem a voucher code for the instance, and return the redemption.

        A boost applies from the next read or report, for its duration; a ``PRICE`` voucher
        discounts the subscription's next invoices.
        """
        return self._api.send(
            "POST",
            api_path("instances", instance_slug, "vouchers", "redeem"),
            Redemption,
            body={"code": code},
        )

    def revoke(self, instance_slug: str, instance_voucher_id: str, *, reason: str) -> Redemption:
        """Stop a redemption applying: a boost ends at once, a discount applies to no further invoice.

        Invoices already issued are untouched.

        Args:
            instance_slug: The instance.
            instance_voucher_id: The redemption's id.
            reason: Why, 1 to 500 characters.
        """
        return self._api.send(
            "POST",
            api_path("instances", instance_slug, "vouchers", instance_voucher_id, "revoke"),
            Redemption,
            body={"reason": reason},
        )
